 async function generateDayBrief(){setBriefBusy(true);setError('');try{const now=Date.now(),pending=tasks.filter(t=>t.status==='pending'),lateTasks=pending.filter(t=>t.due_at&&new Date(t.due_at).getTime()<now),lateReminders=reminders.filter(r=>!r.done&&new Date(r.remind_at).getTime()<now),todayKey=localDateKey(),todayAgenda=events.filter(e=>localDateKey(new Date(e.starts_at))===todayKey),returns=contacts.filter(c=>c.next_contact_at&&new Date(c.next_contact_at).getTime()<=now);const ranked=pending.slice().sort((a,b)=>((b.priority==='high'?30:0)+(b.due_at&&new Date(b.due_at).getTime()<now?100:0))-((a.priority==='high'?30:0)+(a.due_at&&new Date(a.due_at).getTime()<now?100:0))).slice(0,3);const parts=[];if(lateTasks.length)parts.push(`${lateTasks.length} tarefa${lateTasks.length>1?'s':''} atrasada${lateTasks.length>1?'s':''}`);if(lateReminders.length)parts.push(`${lateReminders.length} lembrete${lateReminders.length>1?'s':''} vencido${lateReminders.length>1?'s':''}`);if(returns.length)parts.push(`${returns.length} retorno${returns.length>1?'s':''} pendente${returns.length>1?'s':''}`);if(todayAgenda.length)parts.push(`${todayAgenda.length} compromisso${todayAgenda.length>1?'s':''} hoje`);const focus=ranked.map(t=>t.title);const summary=parts.length?`Seu foco de hoje: ${parts.join(', ')}.${focus.length?' Priorize: '+focus.join(' → ')+'.':''}`:`Seu dia está sob controle.${focus.length?' Próximas prioridades: '+focus.join(' → ')+'.':' Não há pendências urgentes agora.'}`;setDayBrief(summary);const {error:e}=await supabase.from('daily_briefs').upsert({user_id:session.user.id,brief_date:todayKey,summary,focus_items:focus},{onConflict:'user_id,brief_date'});if(e)throw e;activity('ai','Resumo inteligente do dia atualizado')}catch(e){console.error(e);setError('Não foi possível gerar o resumo inteligente.')}finally{setBriefBusy(false)}}
