 async function addSale(){setError('');const amount=Number(sa.replace(',','.'));if(!sd.trim()){setError('Informe o produto ou a descrição da venda.');return}if(!Number.isFinite(amount)||amount<=0){setError('Informe um valor de venda maior que zero.');return}const {data,error:e}=await supabase.from('sales').insert({customer:sc.trim()||null,description:sd.trim(),amount,sold_at:localDateKey(),notes:saleNotes.trim()||null,user_id:session.user.id}).select().single();if(e||!data){setError('Não foi possível registrar a venda.');return}setSales([data,...sales]);activity('sale','Venda registrada: '+sd.trim());setSc('');setSd('');setSa('');setSaleNotes('')}
